// geo/shapes.bynk
commons geo.shapes

type Shape = | Circle(radius: Float) | Square(side: Float)

// app/main.bynk
context app.main

uses geo.shapes

fn unit() -> Shape {
    Circle(1.0)                          // ✗ constructors are not in scope here
}

// geo/shapes.bynk
fn unitCircle() -> Shape { Circle(1.0) } // ✓ built in the commons

// app/main.bynk
fn unit() -> Shape {
    unitCircle()                         // ✓ called from the context
}
